SELECT p.gender, p.age, p.hadm_id, p.died_in_hospital, p.cause_of_death, p.composite_risk_score, q.name AS quartile_name, COUNT(DISTINCT p.subject_id) AS patient_count, SUM(CASE WHEN p.died_in_hospital THEN 1 ELSE 0 END) AS mortality_count, SUM(CASE WHEN p.cause_of_death = 'cardiac' THEN 1 ELSE 0 END) AS cardiac_complication_count, SUM(CASE WHEN p.cause_of_death = 'neurologic' THEN 1 ELSE 0 END) AS neurologic_complication_count, AVG(p.los) AS average_length_of_stay FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN quartiles q ON p.composite_risk_score BETWEEN q.lower_bound AND q.upper_bound WHERE p.gender = 'F' AND p.age BETWEEN 44 AND 54 AND p.died_in_hospital = 1 AND p.cause_of_death = 'intracranial hemorrhage' GROUP BY p.gender, p.age, p.hadm_id, q.name ORDER BY p.gender, p.age, q.name;